def f(inp):
    inp=np.array(inp); out=[]
    for bi in range(inp.shape[0]//3):
        row=[]
        for bj in range(inp.shape[1]//3):
            blk=inp[bi*3:(bi+1)*3, bj*3:(bj+1)*3]
            nz=[v for v in np.unique(blk) if v!=5]
            d={}
            for v in nz: d[v]=int((blk==v).sum())
            row.append(max(d,key=d.get))
        out.append(row)
    return out
